script:
frappe.ui.form.on('Tax Applicability', {

    refresh: function(frm) {
        toggle_sections(frm);
    },

    tax_country: function(frm) {
        load_taxes(frm);
    }
});
const VAT_TAXES = ["UAE-VAT"];
const CT_TAXES = ["UAE-CT"];

function toggle_sections(frm) {

    let vat_enabled = false;
    let ct_enabled = false;

    (frm.doc.table_eeln || []).forEach(function(row) {

        if (VAT_TAXES.includes(row.tax_name) && row.applicable) {
            vat_enabled = true;
        }

        if (CT_TAXES.includes(row.tax_name) && row.applicable) {
            ct_enabled = true;
        }
    });

    frm.toggle_display("uae_vat_section", vat_enabled);
    frm.toggle_display("section_break_cgss", ct_enabled);
}

frappe.ui.form.on('Applicable Taxes', {

    applicable: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        // Clear fields if unchecked
        if (!row.applicable) {
            frappe.model.set_value(cdt, cdn, "tax_basis", "");
            frappe.model.set_value(cdt, cdn, "calculation_basis", "");
        }

        // IMPORTANT: trigger parent section toggle immediately
        toggle_sections(frm);
    }
});
